class BSTIterator {
 public:
  BSTIterator(TreeNode* root, bool leftToRight) : leftToRight(leftToRight) {
    pushUntilNull(root);
  }

  TreeNode* next() {
    TreeNode* root = nodes.top();
    nodes.pop();
    pushUntilNull(leftToRight ? root->right : root->left);
    return root;
  }

 private:
  std::stack<TreeNode*> nodes;
  bool leftToRight;

  void pushUntilNull(TreeNode* root) {
    while (root != nullptr) {
      nodes.push(root);
      root = leftToRight ? root->left : root->right;
    }
  }
};

class Solution {
 public:
  bool findTarget(TreeNode* root, int k) {
    if (root == nullptr)
      return false;

    BSTIterator left(root, true);
    BSTIterator right(root, false);

    for (TreeNode* l = left.next(), *r = right.next(); l != r;) {
      const int sum = l->val + r->val;
      if (sum == k)
        return true;
      if (sum < k)
        l = left.next();
      else
        r = right.next();
    }

    return false;
  }
};
